object NbFonts {
    /** System face for all translated text (only weights 400 and 700, see tokens.json). */
    val sans: FontFamily = FontFamily.Default

    /** Inter (tabular figures): digits, S/B, OUT, VS, R, room codes, #tags, m:ss and % only. Latin only, never translated strings. */
    val num: FontFamily = FontFamily(
        Font(R.font.inter_medium, FontWeight.Medium),
        Font(R.font.inter_semibold, FontWeight.SemiBold),
        Font(R.font.inter_bold, FontWeight.Bold),
    )
}

object NbType {
    /** DESIGN_SYSTEM 16: no font padding and centred line height, so numerals sit exactly in their plates. */
    private val platform = PlatformTextStyle(includeFontPadding = false)
    private val lineHeightStyle = LineHeightStyle(LineHeightStyle.Alignment.Center, LineHeightStyle.Trim.None, LineHeightStyle.Mode.Fixed)

    /** Korean wraps between words (CSS `word-break: keep-all` in the prototype), not between syllables. */
    private val lineBreak = LineBreak(LineBreak.Strategy.HighQuality, LineBreak.Strictness.Normal, LineBreak.WordBreak.Phrase)

    private fun sans(size: Int, line: Int, weight: FontWeight) = TextStyle(
        fontFamily = NbFonts.sans,
        fontSize = size.sp,
        lineHeight = line.sp,
        fontWeight = weight,
        letterSpacing = 0.sp,
        platformStyle = platform,
        lineHeightStyle = lineHeightStyle,
        lineBreak = lineBreak,
    )

    private fun num(size: Int, line: Int, weight: FontWeight, tracking: Double = 0.0) = TextStyle(
        fontFamily = NbFonts.num,
        fontSize = size.sp,
        lineHeight = line.sp,
        fontWeight = weight,
        letterSpacing = tracking.em,
        fontFeatureSettings = "tnum",
        platformStyle = platform,
        lineHeightStyle = lineHeightStyle,
    )

    /** Long legal text: 15 / 24 sp (15-legal-reader). */
    val reading = sans(15, 24, FontWeight.Normal)

    val display = sans(40, 48, FontWeight.Bold)
    val headline = sans(26, 34, FontWeight.Bold)
    val title = sans(20, 28, FontWeight.Bold)
    val subtitle = sans(16, 22, FontWeight.Bold)
    val body = sans(15, 22, FontWeight.Normal)
    val bodyStrong = sans(15, 22, FontWeight.Bold)
    val label = sans(16, 20, FontWeight.Bold)
    val labelSmall = sans(13, 18, FontWeight.Bold)
    val caption = sans(13, 18, FontWeight.Normal)
    val micro = sans(12, 16, FontWeight.Bold)

    val numHero = num(48, 56, FontWeight.Bold)
    val numScore = num(48, 56, FontWeight.Bold, tracking = -0.01)
    val numSlot = num(32, 40, FontWeight.Bold)
    val numCode = num(28, 36, FontWeight.Bold)
    val numStat = num(28, 32, FontWeight.Bold, tracking = -0.01)
    val numKey = num(24, 32, FontWeight.SemiBold)
    val numSlotSm = num(26, 32, FontWeight.Bold, tracking = 0.12)
    val numSummary = num(22, 30, FontWeight.Bold)
    val numLog = num(21, 28, FontWeight.SemiBold, tracking = 0.14)
    val numTimer = num(18, 24, FontWeight.Bold)
    val numMemo = num(18, 24, FontWeight.SemiBold)
    val numHint = num(15, 20, FontWeight.Bold, tracking = 0.02)
    val numTag = num(15, 20, FontWeight.Medium)
    val numLabel = num(13, 16, FontWeight.SemiBold, tracking = 0.02)
}

